    constructor(id, fuel) {
        this.id = id;
        this.fuel = fuel;
    }

    launch() {
        if (this.fuel > 10) {
            this.fuel -= 10;
            return `${this.id} launched successfully! Fuel remaining: ${this.fuel} units.`;
