class CargoShip extends Spacecraft {
    #currentCargo; // Private field

    constructor(id, fuel, cargoCapacity) {
        super(id, fuel);
        this.cargoCapacity = cargoCapacity;
        this.#currentCargo = 0;
    }

    loadCargo(weight) {
        if (this.#currentCargo + weight <= this.cargoCapacity) {
            this.#currentCargo += weight;
            return `Loaded ${weight} units. Current cargo: ${this.#currentCargo}/${this.cargoCapacity}.`;
        }
        return `Cannot load ${weight} units. Capacity exceeded!`;
    }

    unloadCargo(weight) {
        if (this.#currentCargo - weight >= 0) {
            this.#currentCargo -= weight;
            return `Unloaded ${weight} units. Current cargo: ${this.#currentCargo}/${this.cargoCapacity}.`;
        } 
        return `Cannot unload ${weight} units. Not enough cargo.`;
    }

    performMission() {
        if (this.#currentCargo > 0 && this.fuel >= 20) {
            this.fuel -= 20; // Simulate fuel cost for mission
            const deliveredCargo = this.#currentCargo;
            this.#currentCargo = 0; // All cargo delivered
            return `${this.id} successfully completed cargo delivery of ${deliveredCargo} units. Fuel remaining: ${this.fuel}.`;
        } else if (this.#currentCargo === 0) {
            return `${this.id} completed mission: No cargo to deliver. Fuel: ${this.fuel}.`;
        } else {
            return `${this.id} mission failed: Insufficient fuel or cargo for delivery. Fuel: ${this.fuel}, Cargo: ${this.#currentCargo}.`;
        }
    }

    reportStatus() {
        const fuelStatus = `Fuel: ${this.fuel} units.`;
        const cargoStatus = `Cargo: ${this.#currentCargo}/${this.cargoCapacity} units.`;
        return `${this.id} Status: ${fuelStatus} ${cargoStatus}`;
    }
}

